class AurenTrip{final String id,ownerId,title,destination;final DateTime? startDate,endDate;final List<String> placeIds;const AurenTrip({required this.id,required this.ownerId,required this.title,required this.destination,required this.placeIds,this.startDate,this.endDate});factory AurenTrip.fromMap(String id,Map<String,dynamic> d)=>AurenTrip(id:id,ownerId:d['ownerId']??'',title:d['title']??'',destination:d['destination']??'',placeIds:List<String>.from(d['placeIds']??const []),startDate:(d['startDate'] as Timestamp?)?.toDate(),endDate:(d['endDate'] as Timestamp?)?.toDate());}